"""Seal final artifacts after all producers have exited; no numerical work."""
import json,hashlib,time,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'reports/assumption-symmetry_insertion-001';SRC=ROOT/'research/experiments/assumption_symmetry_insertion'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
for p in OUT.glob('*active.json'):
 assert json.loads(p.read_text())['pid'] is None,p
checks=[('receipt.json','pilot.py'),('boundary-receipt.json','boundary.py'),('obstruction.json','obstruction.py'),('finite-check.json','finite_check.py'),('obstruction-independent-check.json','check_obstruction.py'),('coarse-extension.json','coarse_extension.py'),('coarse-extension-independent-check.json','check_extension.py')]
for record,script in checks:assert json.loads((OUT/record).read_text())['source_sha256']==sha(SRC/script),(record,script)
audit=json.loads((OUT/'independent-candidate-audit-175.json').read_text());assert audit['candidate_sha256']==sha(OUT/'checked-positive-mass-witness.json')
paths=list(SRC.glob('*.py'))+list(OUT.glob('*.json'))+list(OUT.glob('*.log'))+[OUT/'REPORT.md',ROOT/'research/notes/assumption-symmetry_insertion.md',ROOT/'reports/clebsch-size-coarse-002/weighted-k12.json',ROOT/'research/experiments/clebsch_bowl/audit_weighted.py']
paths=[p for p in paths if p.name not in ['manifest.json','seal.log']]
manifest={'git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'sealed_unix':time.time(),'sha256':{str(p.relative_to(ROOT)):sha(p) for p in sorted(paths)},'command_prefix':'OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1 uv run --offline --with numpy --with scipy python','scripts_in_order':['pilot.py','boundary.py','obstruction.py','finite_check.py','check_obstruction.py','finalize.py','coarse_extension.py','check_extension.py','seal.py'],'external_checker':'research/experiments/clebsch_bowl/audit_weighted.py --candidate reports/assumption-symmetry_insertion-001/checked-positive-mass-witness.json --out REPORT_JSON','status':'All numerical jobs completed and reaped; no incumbent change or promotion. Report and research note final.','timeout_note':'Original standalone audit used its180s alarm and finished<.1s; repeat independently supervised with175s timeout. All lane numerical scripts use175s internal alarm. Supervisor success/failure/timeout fixtures checked and children reaped.','claims':'Numerical negative screens, exact relative arithmetic restricted obstruction and counterexample, independent numerical193-class recount. No formal kernel certificate or global optimum.','excluded':'Manifest self-hash, generated bytecode, and seal stdout; no mutable output log is hashed before its producer exits.'}
tmp=OUT/'manifest.tmp';tmp.write_text(json.dumps(manifest,indent=2)+'\n');tmp.replace(OUT/'manifest.json')
for path,digest in manifest['sha256'].items():assert sha(ROOT/path)==digest,path
print('SEALED',len(manifest['sha256']),'artifacts; source receipts and candidate audit hashes match; all worker statuses inactive')
